{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Interventions for treatment of COVID-19: A living systematic review with meta-analyses and trial sequential analyses (The LIVING Project)",
      "reason": "The title explicitly identifies the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Interventions for treatment of COVID-19: A living systematic review with meta-analyses and trial sequential analyses",
      "reason": "The title states the population/condition (COVID-19) and the focus (treatment interventions)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "A living systematic review with meta-analyses and trial sequential analyses",
      "reason": "The title provides supplementary information: living-review status and analysis methods (meta-analyses, trial sequential analyses)."
    }
  ],
  "confidence": 98
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "No evidence-based treatment for COVID-19 currently exist to augment widely used supportive care protocols [7]. ... Many randomized clinical trials assessing the effects of different potential treatments for COVID-19 are currently underway.",
      "reason": "The Introduction describes the current state of knowledge (no evidence-based treatment, many trials underway) and the uncertainty this creates."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "there is an urgent need to continuously surveil and update the aggregated evidence base so that effective interventions, if such exist, are implemented in clinical practice [8]. The present living systematic review with aggregate meta-analyses and trial sequential analyses aims to continuously inform evidence-based guideline recommendations for the treatment of COVID-19",
      "reason": "The importance and need for the review are explicitly explained in the Introduction."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_33",
      "quote": "Wehave identified 4 important reviews that are comparable to our present project [77-80].",
      "reason": "Similar existing reviews are identified and cited, and the need for the current review relative to them is explained, but this appears in the Discussion rather than the Introduction/rationale section."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No proposed mechanism of action for the assessed interventions (e.g., antivirals, corticosteroids) is described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review evaluates individual pharmacological interventions for COVID-19, not complex interventions or delivery contexts, so a logic model is not required."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "There is a need for a living systematic review evaluating the beneficial and harmful effects of all possible interventions for treatment of COVID-19.",
      "reason": "The rationale section states the review aims to evaluate beneficial and harmful effects of interventions for COVID-19, which conveys the objective, but no explicit, formal statement of objectives or questions (e.g., 'The objective of this review was...') is present in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of intervention effects, so planned comparisons apply, but the retrieved evidence contains no PICO (or variant) formulation of populations, interventions, comparators, or planned comparisons; only outcomes are listed (text_13), and the objectives are said to be detailed in the protocol, which is not provided."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "a living systematic review of randomized clinical trials comparing the effects of all treatment interventions for participants in all age groups with COVID-19",
      "reason": "Study design (RCTs), population (all age groups with COVID-19), and interventions (all treatments) are stated, but no full explicit eligibility criteria (settings, follow-up requirements, diagnostic criteria) are detailed in the retrieved evidence; details deferred to the protocol."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Trials were included irrespective of language, publication status, publication year, and publication type.",
      "reason": "Report characteristics (language, publication status, year, type) are explicitly specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No distinction is made between exclusion because outcomes were not measured versus not reported; the only exclusion-related note concerns unusable reporting of results (text_22), which does not address this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "Primary and secondary outcomes were predefined in our protocol [9]... We planned several subgroup analyses, which are described in detail in our protocol [9].",
      "reason": "Comparisons used in syntheses appear from results (e.g., intervention versus standard care/placebo), and subgroup analyses are mentioned but deferred to the protocol; the groups for each synthesis are not fully specified and linked in the Methods text."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No notable restrictions on eligibility (e.g., language or publication limits) were imposed, so no rationale for restrictions is required."
    }
  ],
  "confidence": 70
}

{
  "item_id": "PRISMA_2020_6",
  "elements": [
    {
      "element_id": "prisma_2020_6_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We searched all databases from their inception and until August 7, 2020.",
      "reason": "The date when the sources were last searched is explicitly reported (August 7, 2020)."
    },
    {
      "element_id": "prisma_2020_6_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "searched the Cochrane Central Register of Controlled Trials (CENTRAL) in The Cochrane Library, Medical Literature Analysis and Retrieval System Online (MEDLINE Ovid), Excerpta Medica database (Embase Ovid), Latin American and Caribbean Health Sciences Literature (LILACS; Bireme), Science Citation Index Expanded (SCI-EXPANDED; Web of Science)... CINAHL (EBSCO host)... We searched all databases from their inception and until August 7, 2020.",
      "reason": "Database names, platforms/interfaces (Ovid, Bireme, Web of Science, EBSCO), and coverage dates (inception to August 7, 2020) are all reported."
    },
    {
      "element_id": "prisma_2020_6_e3",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "we searched clinical trial registries (e.g., clinicaltrials.gov, clinicaltrialregister.eu, who.int/ictrp, chictr.org.cn) of Europe, USA, and China, and websites of pharmaceutical companies, websites of US Food and Drug Administration (FDA) and European Medicines Agency (EMA). We also searched the COVID-19 Study Registry [13] and the real-time dashboard of randomized trials [14].",
      "reason": "Registries and repositories are named, but no date restrictions or last-searched dates specific to these registers are reported; the August 7, 2020 date applies to 'all databases'."
    },
    {
      "element_id": "prisma_2020_6_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "websites of pharmaceutical companies, websites of US Food and Drug Administration (FDA) and European Medicines Agency (EMA). We also searched... preprint servers (bioRxiv, medRxiv)",
      "reason": "Websites and preprint servers are named, but URLs are not provided (only registry URLs are given)."
    },
    {
      "element_id": "prisma_2020_6_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No organisations or manufacturers are reported as contacted to identify studies; pharmaceutical company websites were searched, not the companies contacted."
    },
    {
      "element_id": "prisma_2020_6_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Trial authors were contacted only to obtain individual patient data, not to identify studies; no individuals contacted for study identification are described."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "The reference lists of relevant trial publications were checked for any unidentified randomized clinical trials.",
      "reason": "The type of reference lists examined (relevant trial publications) is specified."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_9",
      "quote": "Electronic searches... Searching other resources. The reference lists of relevant trial publications were checked...",
      "reason": "No backward/forward citation searching using a citation index is reported; only manual reference list checking, which is covered by e7."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "Conference Proceedings Citation Index-Science (CPCI-S; Web of Science)... We searched all databases from their inception and until August 7, 2020.",
      "reason": "Conference proceedings are covered via the CPCI-S database with platform and coverage dates, but no separate handsearching of journals or proceedings with specific methods is described."
    }
  ],
  "confidence": 88
}

