{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Primary outcomes were all-cause mortality and serious adverse events (as defined by the International Conference on Harmonation-Good Clinical Practice [ICH-GCP] guidelines) [9,16]. Secondary outcomes were admission to intensive care (as defined by trialists), receipt of mechanical ventilation (as defined by trialists), receipt of renal replacement therapy (as defined by trialists), quality of life, and nonserious adverse events. We classified nonserious adverse events as any adverse event not assessed as serious according to the ICH-GCP definition.",
      "reason": "All primary and secondary outcome domains are listed and defined, including definitions referencing ICH-GCP and trialist definitions."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "For all outcomes, we used the trial results reported at maximum follow-up.",
      "reason": "The time frame of measurement is specified as trial results at maximum follow-up for all outcomes."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly state whether all compatible results (all measures, time points, analyses) within each outcome domain were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that only a subset of compatible results was sought, so no selection process needed describing."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "PARTIAL",
      "chunk_id": "text_35",
      "quote": "Further, we included 'time to clinical improvement' as an outcome post hoc.",
      "reason": "The post hoc addition of an outcome is reported, but no rationale for the change is provided."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to processes for selecting results within outcome domains are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although primary and secondary outcomes are distinguished, no explicit statement identifies which outcomes were considered most important for interpreting conclusions or the rationale for their prioritisation."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PARTIAL",
      "chunk_id": "text_13",
