    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Risk of bias was assessed with the Cochrane Risk of Bias tool-version 2 (RoB 2) [12,15].",
      "reason": "The tool and version (Cochrane RoB 2) are explicitly specified."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Bias was assessed with the following domains: bias arising from the randomization process, bias due to deviations from the intended interventions, bias due to missing outcome data, bias in measurement of outcomes, and bias arising from selective reporting of results [12,15].",
      "reason": "All five RoB 2 domains assessed are listed."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "All trials were assessed as at high risk of bias ( S3 Table ).",
      "reason": "Overall risk-of-bias judgements are reported (all trials at high risk; see also text_2), but the rules used to derive the overall judgement are not described."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_12",
      "quote": "Risk of bias was assessed with the Cochrane Risk of Bias tool-version 2 (RoB 2) [12,15].",
      "reason": "The standard RoB 2 tool was used with its stated domains; no adaptations to the tool are reported."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_12",
      "quote": "Risk of bias was assessed with the Cochrane Risk of Bias tool-version 2 (RoB 2) [12,15].",
      "reason": "Only an existing tool (RoB 2) was used; no new tool was developed."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Six authors in pairs (SJ, EEN, JF, FS, CKJ, EB) independently assessed risk of bias. Any discrepancies were resolved through discussion or, if required, through discussion with a third author (JCJ).",
      "reason": "Number of reviewers, independent paired assessment, and disagreement-resolution procedures are reported."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Wecontacted authors of trials with unclear or missing data.",
      "reason": "The process of contacting trial authors to obtain or confirm information is described, albeit briefly."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_12",
      "quote": "Six authors in pairs (SJ, EEN, JF, FS, CKJ, EB) independently assessed risk of bias.",
      "reason": "Risk of bias was assessed manually by authors; no automation tools are reported or implied."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "We used risk ratios (RRs) for dichotomous outcomes. We planned to calculate the mean differences (MDs) and standardized mean difference (SMD) with 95% confidence intervals (CI) for continuous outcomes.",
      "reason": "Methods specify effect measures by outcome type: RRs for dichotomous outcomes and MD/SMD for continuous outcomes."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "We assessed a total of 2 primary outcomes, and we therefore adjusted our thresholds for significance [18] and considered a p-value of 0.033 or less as the threshold for statistical significance [9,18].",
      "reason": "Thresholds for interpreting significance are reported with rationale (adjustment for two primary outcomes); TSA also uses a 20% relative risk reduction assumption."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence describes re-expressing synthesized results using another effect measure."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "We conducted both random-effects (Inverse Variance, DerSimonian-Laird) and fixed-effect (Mantel-Haenszel) meta-analyses for all analyses and chose the most conservative result as our primary result [12,18,21,22].",
      "reason": "Choice of analysis model is justified by reference to conservative-result selection and cited methods, but no explicit justification for choosing RR/MD as effect measures is provided."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence describes data extraction, outcomes, and statistical synthesis methods, but no process is described for deciding which studies were eligible for each synthesis (e.g., tabulating study intervention characteristics and comparing them against planned synthesis groups). The comparisons are only listed retrospectively in the Results section (text_15), not as an eligibility-decision process in the Methods."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_13b",
  "elements": [
    {
      "element_id": "prisma_2020_13b_e1",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "We used risk ratios (RRs) for dichotomous outcomes. We planned to calculate the mean differences (MDs) and standardized mean difference (SMD) with 95% confidence intervals (CI) for continuous outcomes.",
      "reason": "The manuscript describes some data preparation/conversion choices (effect measure selection for dichotomous and continuous outcomes) and mentions contacting trial authors when data were unclear or missing (text_11, text_12), but it does not explicitly describe handling of missing summary statistics or detailed data conversion procedures (e.g., imputation or unit conversions)."
    }
  ],
  "confidence": 70
}

{
  "item_id": "PRISMA_2020_13c",
  "elements": [
    {
      "element_id": "prisma_2020_13c_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence lists many tables (e.g., 'S4 Table. Summary of findings table of dexamethasone versus standard care') but the Methods section contains no description of the tabular structures used to display results or the data included in them."
    },
    {
      "element_id": "prisma_2020_13c_e2",
      "status": "PARTIAL",
